100	function slugify(name: string): string {
101	  const raw = name
102	    .toLowerCase()
103	    .replace(/[^a-z0-9]+/g, "-")
104	    .replace(/^-|-$/g, "")
105	    .slice(0, 60);
106	  // DB constraint requires minimum 3 chars starting and ending with alphanumeric.
107	  if (raw.length < 3) return raw.padEnd(3, "1");
108	  return raw;
109	}
110	
111	// DB constraint only accepts 6-digit hex (#rrggbb).
112	function isValidHex(value: string): boolean {
113	  return /^#[0-9A-Fa-f]{6}$/.test(value);
114	}
